type FormState = {
  values: { message: string };
  isDirty: boolean;
};

article.sections.7.blocks.4.text:
async function submitForm(
  state: FormState,
  save: (values: FormState["values"]) => Promise<void>,
): Promise<void> {
  await save({ ...state.values });
  state.isDirty = false;
}
